const items = $input.all();
const tree = items[0]?.json?.tree || [];
const processed = [];

// Filter for official markdown files in docs/ folder
const docFiles = tree.filter(file => 
  file.path && 
  file.path.startsWith('docs/') && 
  file.path.endsWith('.md') && 
  !file.path.includes('.github')
);

for (const file of docFiles) {
  const pathParts = file.path.split('/');
  const category = pathParts.length > 2 ? pathParts[1] : 'general';
  const fileName = pathParts[pathParts.length - 1].replace('.md', '');
  const title = fileName.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  const rawUrl = `https://raw.githubusercontent.com/n8n-io/n8n-docs/main/${file.path}`;

  processed.push({
    json: {
      metadata: {
        doc_type: 'official_doc',
        category: category,
        file_path: file.path,
        title: title,
        raw_url: rawUrl
      }
    }
  });
}

return processed;

const items = $input.all();
const processed = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];

  // Explicitly reference Node #3 metadata by exact name
  const metadata = $('Parse Doc File List').all()[i]?.json?.metadata || {};

  // Extract text response
  const fileContent = typeof item.json.data === 'string' ? item.json.data : (typeof item.json === 'string' ? item.json : '');

  if (!fileContent || fileContent.trim().length === 0) continue;

  const cleanContent = fileContent.trim();
  const sections = cleanContent.split(/(?=\n#{1,3}\s)/g);

  let chunkIndex = 1;
  for (const section of sections) {
    const trimmed = section.trim();
    if (trimmed.length < 50) continue;

    const headingMatch = trimmed.match(/^#{1,3}\s+(.+)$/m);
    const sectionHeading = headingMatch ? headingMatch[1].replace(/[*_~`]/g, '') : 'General Overview';

    const maxChunkLen = 1500;

    if (trimmed.length > maxChunkLen) {
      const paragraphs = trimmed.split(/\n\n+/);
      let currentChunk = '';

      for (const para of paragraphs) {
        if ((currentChunk + '\n\n' + para).length > maxChunkLen && currentChunk.length > 0) {
          processed.push({
            json: {
              pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading} (Part ${chunkIndex})\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${currentChunk}`,
              metadata: {
                ...metadata,
                section_heading: sectionHeading,
                chunk_index: chunkIndex
              }
            }
          });
          chunkIndex++;
          currentChunk = para;
        } else {
          currentChunk = currentChunk ? `${currentChunk}\n\n${para}` : para;
        }
      }

      if (currentChunk.trim().length > 30) {
        processed.push({
          json: {
            pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading} (Part ${chunkIndex})\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${currentChunk}`,
            metadata: {
              ...metadata,
              section_heading: sectionHeading,
              chunk_index: chunkIndex
            }
          }
        });
        chunkIndex++;
      }
    } else {
      processed.push({
        json: {
          pageContent: `### ${metadata.title || 'Doc'} > ${sectionHeading}\n**Category:** ${metadata.category || 'general'}\n**Source:** ${metadata.file_path || ''}\n\n${trimmed}`,
          metadata: {
            ...metadata,
            section_heading: sectionHeading,
            chunk_index: chunkIndex
          }
        }
      });
      chunkIndex++;
    }
  }
}

return processed;

const staticData = $getWorkflowStaticData('global');
const currentSha = $input.all()[0]?.json?.sha;

if (!currentSha) {
  throw new Error("Could not retrieve commit SHA from GitHub API.");
}

// 1. INITIAL SEEDING: If no SHA is saved yet, save today's SHA and STOP!
if (!staticData.lastDocCommitSha) {
  staticData.lastDocCommitSha = currentSha;
  console.log(`Seeded workflow memory with today's commit SHA (${currentSha}). Skipping ingestion until next change.`);
  return []; // Stops workflow execution right here
}

// 2. CHECK FOR CHANGES: Compare current SHA with stored SHA
if (currentSha === staticData.lastDocCommitSha) {
  console.log(`No documentation updates detected. Current SHA (${currentSha}) matches stored SHA.`);
  return []; // Stops workflow execution right here
}

// 3. UPDATES FOUND: Update stored SHA and pass execution forward
console.log(`New documentation commit detected! Updating SHA to ${currentSha}`);
staticData.lastDocCommitSha = currentSha;

return [{
  json: {
    status: 'UPDATES_FOUND',
    currentSha: currentSha
  }
}];
